/**
 * P-15 Cleanup: Delete shadow blocks generated by calendars with shadowSource=false
 * (Team StartOut, Family) and self-loop blocks where source=target calendar.
 *
 * For each erroneous block that has an externalEventId, we also delete the
 * Google Calendar event if a valid token is available.
 *
 * Run: node scripts/cleanup-shadow-source-violations.mjs
 */
import mysql from "mysql2/promise";

const conn = await mysql.createConnection(process.env.DATABASE_URL);

const CALENDAR_API_BASE = "https://www.googleapis.com/calendar/v3";

async function refreshAccessToken(refreshToken) {
  const resp = await fetch("https://oauth2.googleapis.com/token", {
    method: "POST",
    headers: { "Content-Type": "application/x-www-form-urlencoded" },
    body: new URLSearchParams({
      client_id: process.env.GOOGLE_CLIENT_ID,
      client_secret: process.env.GOOGLE_CLIENT_SECRET,
      refresh_token: refreshToken,
      grant_type: "refresh_token",
    }),
  });
  const data = await resp.json();
  if (!data.access_token) throw new Error(`Token refresh failed: ${JSON.stringify(data)}`);
  return data.access_token;
}

async function deleteGCalEvent(accessToken, calendarExternalId, eventId) {
  const resp = await fetch(
    `${CALENDAR_API_BASE}/calendars/${encodeURIComponent(calendarExternalId)}/events/${encodeURIComponent(eventId)}`,
    { method: "DELETE", headers: { Authorization: `Bearer ${accessToken}` } }
  );
  if (!resp.ok && resp.status !== 410 && resp.status !== 404) {
    throw new Error(`GCal delete failed: ${resp.status}`);
  }
}

// ── 1. Identify opted-out source calendars ──────────────────────────────────
const [optedOutSources] = await conn.execute(
  "SELECT id, name FROM calendars WHERE shadowSource = 0"
);
console.log(`\nOpted-out source calendars (shadowSource=false):`);
optedOutSources.forEach((c) => console.log(`  ${c.id}  ${c.name}`));

const sourceIds = optedOutSources.map((c) => c.id);

// ── 2. Count erroneous blocks ───────────────────────────────────────────────
let totalFromSources = 0;
if (sourceIds.length > 0) {
  const placeholders = sourceIds.map(() => "?").join(",");
  const [[{ cnt }]] = await conn.execute(
    `SELECT COUNT(*) AS cnt FROM shadow_blocks WHERE sourceCalendarId IN (${placeholders})`,
    sourceIds
  );
  totalFromSources = Number(cnt);
}
const [[{ selfCnt }]] = await conn.execute(
  "SELECT COUNT(*) AS selfCnt FROM shadow_blocks WHERE sourceCalendarId = targetCalendarId"
);
const totalSelfLoops = Number(selfCnt);

console.log(`\nShadow blocks from opted-out sources: ${totalFromSources}`);
console.log(`Self-loop shadow blocks: ${totalSelfLoops}`);

if (totalFromSources + totalSelfLoops === 0) {
  console.log("\nNothing to clean up. Exiting.");
  await conn.end();
  process.exit(0);
}

// ── 3. Collect GCal events to delete ───────────────────────────────────────
let gcalEventsToDelete = [];

if (sourceIds.length > 0) {
  const placeholders = sourceIds.map(() => "?").join(",");
  const [rows] = await conn.execute(
    `SELECT sb.id, sb.targetCalendarId, sb.externalEventId,
            c.externalId AS calExternalId, c.memberId
     FROM shadow_blocks sb
     JOIN calendars c ON c.id = sb.targetCalendarId
     WHERE sb.sourceCalendarId IN (${placeholders}) AND sb.externalEventId IS NOT NULL`,
    sourceIds
  );
  gcalEventsToDelete.push(...rows);
}

const [selfRows] = await conn.execute(
  `SELECT sb.id, sb.targetCalendarId, sb.externalEventId,
          c.externalId AS calExternalId, c.memberId
   FROM shadow_blocks sb
   JOIN calendars c ON c.id = sb.targetCalendarId
   WHERE sb.sourceCalendarId = sb.targetCalendarId AND sb.externalEventId IS NOT NULL`
);
gcalEventsToDelete.push(...selfRows);

// Deduplicate by externalEventId
const seen = new Set();
gcalEventsToDelete = gcalEventsToDelete.filter((r) => {
  const key = `${r.targetCalendarId}:${r.externalEventId}`;
  if (seen.has(key)) return false;
  seen.add(key);
  return true;
});

console.log(`\nGCal events to delete: ${gcalEventsToDelete.length}`);

// ── 4. Delete GCal events ───────────────────────────────────────────────────
let gcalDeleted = 0;
let gcalFailed = 0;
const tokenCache = {};

for (const row of gcalEventsToDelete) {
  if (!row.calExternalId || !row.externalEventId) continue;

  // Get refresh token for the member who owns this calendar
  if (!tokenCache[row.memberId]) {
    const [tokenRows] = await conn.execute(
      "SELECT refreshToken FROM oauth_tokens WHERE memberId = ? AND provider = 'google' AND status = 'active' LIMIT 1",
      [row.memberId]
    );
    if (!tokenRows.length) {
      gcalFailed++;
      continue;
    }
    try {
      tokenCache[row.memberId] = await refreshAccessToken(tokenRows[0].refreshToken);
    } catch {
      gcalFailed++;
      continue;
    }
  }

  try {
    await deleteGCalEvent(tokenCache[row.memberId], row.calExternalId, row.externalEventId);
    gcalDeleted++;
    if (gcalDeleted % 50 === 0) process.stdout.write(`  GCal deleted: ${gcalDeleted}...\n`);
  } catch (err) {
    gcalFailed++;
    if (gcalFailed <= 5) console.log(`  GCal delete error: ${err.message}`);
  }
}

console.log(`GCal: ${gcalDeleted} deleted, ${gcalFailed} failed/skipped`);

// ── 5. Delete DB rows ───────────────────────────────────────────────────────
let dbDeleted = 0;

if (sourceIds.length > 0) {
  const placeholders = sourceIds.map(() => "?").join(",");
  const [result] = await conn.execute(
    `DELETE FROM shadow_blocks WHERE sourceCalendarId IN (${placeholders})`,
    sourceIds
  );
  dbDeleted += result.affectedRows;
  console.log(`\nDB rows deleted (opted-out sources): ${result.affectedRows}`);
}

const [selfResult] = await conn.execute(
  "DELETE FROM shadow_blocks WHERE sourceCalendarId = targetCalendarId"
);
dbDeleted += selfResult.affectedRows;
console.log(`DB rows deleted (self-loops): ${selfResult.affectedRows}`);

console.log(`\n✓ Total DB rows deleted: ${dbDeleted}`);
console.log(`✓ Total GCal events deleted: ${gcalDeleted}`);

await conn.end();
